import { withBase } from "./pack";

// ============================================================================
// AIRCRAFT COLLECTION
// The catalog (public/data/collection.json, generated by `npm run packs`) lists
// every aircraft across all packs. The player's record tracks which they've
// caught. Everything here is pure: storage lives in collectionStore.ts, so a
// sync backend can replace it without touching this file or the UI.
// ============================================================================

export interface CatalogFacts {
  description: string | null;
  role: string | null;
  manufacturer: string | null;
  firstFlight: number | null;
  country: string | null;
  /** First sentences of the Wikipedia summary (CC BY-SA: show with `wikipedia`). */
  about: string | null;
  wikipedia: string | null;
}

export interface CatalogEntry {
  /** Permanent entry number, e.g. 42 for "#042". */
  number: number;
  name: string;
  /** Path under public/, or an absolute URL. */
  image: string;
  credit: string | null;
  /** Ids of every pack the aircraft appears in, in menu order. */
  packs: string[];
  /** Only for entries outside the aircraft dataset. */
  caption?: string;
  /** Only for dataset aircraft. */
  facts?: CatalogFacts;
}

export interface Catalog {
  entries: Record<string, CatalogEntry>;
  /** "<pack id>/<answer id>" -> entry key. */
  aliases: Record<string, string>;
}

export interface EntryProgress {
  /** ISO time of the first correct answer; absent until caught. */
  firstCaughtAt?: string;
  /** Times shown as a question and finished (answered or timed out). */
  seen: number;
  /** Times answered correctly. */
  correct: number;
  /** Whether the detail card has been opened since catching (clears the "New" tag). */
  viewed: boolean;
}

export interface CollectionRecord {
  version: 1;
  entries: Record<string, EntryProgress>;
  updatedAt: string;
}

export function emptyRecord(now = new Date()): CollectionRecord {
  return { version: 1, entries: {}, updatedAt: now.toISOString() };
}

/** The entry a pack question belongs to, or undefined if the catalog doesn't know it. */
export function entryKey(catalog: Catalog, packId: string, answerId: string): string | undefined {
  return catalog.aliases[`${packId}/${answerId}`];
}

export function isCaught(record: CollectionRecord, key: string): boolean {
  return Boolean(record.entries[key]?.firstCaughtAt);
}

/** Records one finished question. A correct answer catches the entry; nothing ever un-catches it. */
export function recordAnswer(
  record: CollectionRecord,
  key: string,
  correct: boolean,
  now = new Date(),
): { record: CollectionRecord; newCatch: boolean } {
  const prev = record.entries[key] ?? { seen: 0, correct: 0, viewed: false };
  const newCatch = correct && !prev.firstCaughtAt;
  const at = now.toISOString();
  const entry: EntryProgress = {
    ...prev,
    seen: prev.seen + 1,
    correct: prev.correct + (correct ? 1 : 0),
    ...(newCatch ? { firstCaughtAt: at, viewed: false } : {}),
  };
  return { record: { ...record, entries: { ...record.entries, [key]: entry }, updatedAt: at }, newCatch };
}

/** Marks a caught entry's detail card as opened. */
export function markViewed(record: CollectionRecord, key: string, now = new Date()): CollectionRecord {
  const entry = record.entries[key];
  if (!entry?.firstCaughtAt || entry.viewed) return record;
  return { ...record, entries: { ...record.entries, [key]: { ...entry, viewed: true } }, updatedAt: now.toISOString() };
}

/**
 * Combines two records (e.g. this device and a synced copy) without losing a
 * catch. Safe to repeat: merging the same records again gives the same result,
 * so counts take the larger value rather than adding up.
 */
export function mergeRecords(a: CollectionRecord, b: CollectionRecord): CollectionRecord {
  const entries: Record<string, EntryProgress> = { ...a.entries };
  for (const [key, y] of Object.entries(b.entries)) {
    const x = entries[key];
    if (!x) {
      entries[key] = y;
      continue;
    }
    const caught = [x.firstCaughtAt, y.firstCaughtAt].filter((t): t is string => Boolean(t)).sort();
    entries[key] = {
      seen: Math.max(x.seen, y.seen),
      correct: Math.max(x.correct, y.correct),
      viewed: x.viewed || y.viewed,
      ...(caught.length ? { firstCaughtAt: caught[0] } : {}),
    };
  }
  return { version: 1, entries, updatedAt: a.updatedAt > b.updatedAt ? a.updatedAt : b.updatedAt };
}

/** Reads a stored record, starting fresh if it's missing, corrupt or from an unknown version. */
export function parseRecord(raw: string | null): CollectionRecord {
  if (!raw) return emptyRecord();
  try {
    const r = JSON.parse(raw);
    if (r?.version === 1 && r.entries && typeof r.entries === "object") return r as CollectionRecord;
  } catch {
    // fall through
  }
  return emptyRecord();
}

/** Entry keys in a pack, deduped, in entry-number order. */
export function packEntries(catalog: Catalog, packId: string): string[] {
  return Object.keys(catalog.entries)
    .filter((key) => catalog.entries[key].packs.includes(packId))
    .sort((x, y) => catalog.entries[x].number - catalog.entries[y].number);
}

export function progress(record: CollectionRecord, keys: readonly string[]): { caught: number; total: number } {
  return { caught: keys.filter((k) => isCaught(record, k)).length, total: keys.length };
}

/** "#007". */
export function formatNumber(n: number): string {
  return `#${String(n).padStart(3, "0")}`;
}

export async function loadCatalog(): Promise<Catalog> {
  const res = await fetch(withBase("data/collection.json"));
  if (!res.ok) throw new Error(`Could not load the collection (${res.status}).`);
  return res.json();
}
